"""Dependency-free static site generator. No LLM guesses or browser-side API keys."""
import csv
import html
import io
import json
import shutil
from datetime import datetime,timezone
from pathlib import Path
from scripts.policy import publication_errors
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'_site'
load=lambda name:json.loads((ROOT/'data'/name).read_text())
SPORTS=load('sports.json');EVENTS=load('observations.json');AUDIT=load('audit.json');PICKS=load('picks.json')
BYSLUG={s['slug']:s for s in SPORTS}
e=html.escape

def link(url,label):return f'<a href="{e(url,quote=True)}" target="_blank" rel="noopener noreferrer">{e(label)} ↗</a>'
def pill(label,kind=''):return f'<span class="pill {kind}">{e(label)}</span>'
def box(title,subtitle,body):return f'<section class="panel"><div class="panelhead"><div><h2>{title}</h2><p>{subtitle}</p></div></div>{body}</section>'
def metric(label,value,note,green=False):return f'<div class="metric"><div class="label">{label}</div><div class="value {"green" if green else ""}">{value}</div><small>{note}</small></div>'
def counts(slug):return sum(x['sport']==slug for x in EVENTS)
def frame(title,body,section='Overview',depth=0):
    base='../'*depth
    def nav(path,label,active=False):
        attr=' class="active"' if active else ''
        return f'<a href="{base}{path}"{attr}>{label}</a>' 
    topnav=nav('index.html','Overview',section=='Overview')+nav('matches/index.html','Event inventory',section=='Inventory')+nav('review/index.html','Flagged for Review <span class="count">!</span>',section=='Review')+nav('methodology/index.html','Pricing & sources',section=='Methodology')+nav('discovery/index.html','Collection log',section=='Discovery')
    sportnav=''.join(nav(f'sports/{s["slug"]}.html',s['name'],section==s['name']) for s in SPORTS)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Independent OLBG event research desk. Evidence-led coverage, pricing research and transparent review flags across 15 sports."><title>{e(title)} · OLBG Research Desk</title><link rel="stylesheet" href="{base}assets/style.css"><script defer src="{base}assets/app.js"></script><link rel="icon" href="{base}assets/favicon.svg" type="image/svg+xml"></head><body><a class="skip" href="#main">Skip to content</a><aside class="sidebar"><a class="brand" href="{base}index.html"><span class="brandmark">O</span><span><strong>Research Desk</strong><small>OLBG event intelligence</small></span></a><div class="navlabel">Workspace</div><nav aria-label="Main navigation" class="nav">{topnav}</nav><div class="navlabel">Sports coverage · 15</div><nav class="nav sports" aria-label="Sports">{sportnav}</nav><div class="sidebarfoot"><a href="{base}../index.html" style="color:#bdd0c3">← Main dashboard</a><br>Evidence before opinion.<br>Independent project. Not affiliated with OLBG.</div></aside><div class="shell"><header class="topbar"><div class="crumb">Workspace <span aria-hidden="true">/</span> <strong>{e(section)}</strong></div><div class="topmeta"><span><span class="dot"></span>Research snapshot</span><span>26 OCT 2026 · UTC</span></div></header><main class="content" id="main"><div class="notice stale" data-snapshot="2026-10-26" hidden><span class="icon">!</span><div><strong>Historical research — not a live betting feed</strong>This source inspection is more than 24 hours old. Review current sources before relying on any event listing.</div></div>{body}<footer class="foot"><span>OLBG Research Desk · Independent research, not bookmaker advice.</span><span>18+ / legal age in your location. No guaranteed outcomes. {link('https://www.ncpgambling.org/','Gambling support')}</span></footer></main></div></body></html>'''

def write(path,content):
    dest=OUT/path;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(content)

def intro(eyebrow,title,lead,action=''):
    return f'<div class="headrow"><div><div class="eyebrow">{eyebrow}</div><h1>{title}</h1><p class="lead">{lead}</p></div>{action}</div>'

def notice():return '<div class="notice"><span class="icon">!</span><div><strong>No actionable picks are published</strong><p>Official evidence and independent pricing are incomplete. Unknown values stay blank; observed listings are not recommendations. The five-picks-per-sport daily target has not been met.</p></div></div>'

def table(headers,rows,caption=''):
    return '<div class="tablewrap"><table>'+('<caption>'+caption+'</caption>' if caption else '')+'<thead><tr>'+''.join('<th scope="col">'+h+'</th>' for h in headers)+'</tr></thead><tbody>'+rows+'</tbody></table></div>'

def sport_table():
    rows=''
    for i,s in enumerate(SPORTS):
        rows+=f'''<tr data-row data-sport="{s['slug']}" data-status="unverified" data-name="{e(s['name'])}"><td><div class="sportname"><span class="sporticon">{i+1:02d}</span><a href="sports/{s['slug']}.html"><strong>{s['name']}</strong></a></div></td><td>{counts(s['slug'])}</td><td><strong>0</strong><span class="sub">Target: 5 per day</span></td><td>{pill('Evidence incomplete','amber')}</td><td>{pill('Not fitted')}</td><td class="sources">{link(s['olbg_urls'][0],'OLBG')}{link(s['official_url'],'Official research source')}</td><td><a class="toolbarlink" href="sports/{s['slug']}.html">Open research →</a></td></tr>'''
    return '<section class="panel" data-filter-panel><div class="filters"><label class="search"><span>Find a sport</span><input data-search type="search" placeholder="Search the 15 covered sports…"></label><label><span>Sort</span><select data-sort><option value="name">Sport name</option><option value="sport">Category</option></select></label></div>'+table(['Sport','Observed entries','Our picks','Evidence','Pricing','Source links','Research'],rows,'Source directory links identify research destinations; they do not confirm individual fixtures.')+'<div class="tablefoot"><span data-result-count></span><span>Football and horse racing excluded · Gaelic Football + Hurling included</span></div></section>'

def observation_table(events,depth=1):
    rows=''
    for x in events:
        s=BYSLUG[x['sport']]
        corroboration=e(x['official_fact'] or 'No fixture-level confirmation collected. The official link is a research destination only.')
        details='<details><summary>Evidence & issues</summary><p>'+corroboration+'</p><ul>'+''.join('<li>'+e(f)+'</li>' for f in x['flags'])+'</ul></details>'
        sources=link(x['olbg_url'],'OLBG event')+'<br>'+link(x['official_url'] or s['official_url'],'Official evidence' if x['official_url'] else 'Official directory only')
        rows+=f'''<tr data-row data-sport="{s['slug']}" data-status="{x['status']}" data-name="{e(x['name'].lower())}"><td class="wrapname"><strong>{e(x['name'])}</strong><span class="sub">{s['name']} · OLBG #{x['id']}</span></td><td>{e(x['raw_time'])}<span class="sub">Raw source clock · timezone unknown<br>Observed {x['observed_on']}</span></td><td>{e(x['official_date'] or '')}<span class="sub">{e(x['official_start_utc'] or '')}</span></td><td class="blank" aria-label="Selection unverified"></td><td class="blank" aria-label="Fair line unverified"></td><td class="blank" aria-label="Confidence unverified"></td><td>{pill('Partial corroboration' if x['status']=='partial' else 'Unverified','green' if x['status']=='partial' else 'amber')}{details}</td><td class="sources">{sources}</td></tr>'''
    options=''.join(f'<option value="{s["slug"]}">{s["name"]}</option>' for s in SPORTS)
    filters=f'<div class="filters"><label class="search"><span>Search events</span><input data-search type="search" placeholder="Team, player, event or issue…"></label><label><span>Sport</span><select data-sport><option value="">All sports</option>{options}</select></label><label><span>Evidence</span><select data-status><option value="">All states</option><option value="partial">Partial corroboration</option><option value="unverified">Unverified</option></select></label><label><span>Sort</span><select data-sort><option value="name">Event A–Z</option><option value="sport">Sport</option></select></label></div>'
    body=table(['Event / race','OLBG display time','Official date / UTC start','Our selection','Our fair line','Confidence','Research state','Sources'],rows,'Blank selection, fair-line and confidence cells are intentional: those fields have not passed the publication criteria.') if events else '<div class="empty"><h3>No entries in the inspected extract</h3><p>This does not establish that no future fixtures or markets exist.</p></div>'
    return '<section class="panel" data-filter-panel>'+filters+body+'<div class="tablefoot"><span data-result-count></span><span>Partial snapshot · not a complete or live fixture feed</span></div></section>'

def main():
    if len(SPORTS)!=15:raise ValueError('Expected exactly 15 sports')
    for p in PICKS:
        errors=publication_errors(p)
        if errors:raise ValueError('Unsafe pick rejected: '+'; '.join(errors))
    # Until production adapters exist, a non-empty picks file must fail closed.
    if OUT.exists():shutil.rmtree(OUT)
    OUT.mkdir();shutil.copytree(ROOT/'assets',OUT/'assets')
    shutil.copytree(ROOT/'data',OUT/'data',ignore=shutil.ignore_patterns('collection'))
    write('.nojekyll','')
    action='<a class="button" href="data/observations.csv" download>↓ Export observations</a>'
    body=intro('Research overview','A clearer view of the next event.','One workspace for fixtures, original pricing research and source-led predictions across 15 sports. See what is known, what is missing, and why a pick has not been released.',action)+notice()
    body+='<div class="metrics">'+metric('Covered sports','15','16 OLBG category pages inspected')+metric('Observed event entries',str(len(EVENTS)),'Partial inventory · not all upcoming')+metric('Actionable predictions','0','No unsupported selections',True)+metric('Sports meeting daily target','0 / 15','5 written picks per sport required')+'</div>'
    body+='''<section class="panel" id="picks"><div class="panelhead"><div><h2>Executive summary · our highest-confidence picks</h2><p>Only eligible, evidence-backed original predictions belong here.</p></div>'''+pill('0 qualifying picks','amber')+'''</div><div class="tabs" role="tablist" aria-label="Pick window"><button data-pick-tab="today" role="tab" aria-selected="true" aria-controls="picks-panel" id="today-tab">Today · 26 Oct <span>0</span></button><button data-pick-tab="upcoming" role="tab" aria-selected="false" aria-controls="picks-panel" id="upcoming-tab">Upcoming <span>0</span></button></div><div class="empty" id="picks-panel" role="tabpanel" aria-label="Qualifying picks"><div class="emptybadge" aria-hidden="true">✓</div><h3 id="picks-empty-heading">No qualifying picks for today</h3><p>No event has the complete official evidence, usable OLBG price and independent calibrated probability required for publication. We will not turn community support into a confidence rating.</p><a class="button primary" href="matches/index.html">Explore the event inventory →</a> <a class="button" href="review/index.html">See what needs review</a></div></section>'''
    body+='<div class="sectionrow"><div><h2>Sport-by-sport coverage</h2><p>Every requested category, with clear evidence and pricing status.</p></div><a href="methodology/index.html" class="toolbarlink">How we assess a pick →</a></div>'+sport_table()
    body+='<div class="split">'+box('What the research established','Field-level corroboration, not a blanket approval.','<div class="bodypad"><ul class="checklist"><li>Official NHL pairings and start times '+pill('3 games','green')+'</li><li>MLB pairing found; OLBG date alignment unresolved '+pill('Needs review','amber')+'</li><li>F1 Mexico and LPGA Maybank event dates found '+pill('Schedule only','green')+'</li><li>ICC / EHF corresponding participants found '+pill('Partial','amber')+'</li></ul></div>')+box('Publication rules','A quota never overrides missing evidence.','<div class="bodypad"><p class="mini">Selections must be between −250 and +10000 American odds, with official fixture, form, recent history and relevant availability evidence. Each published high-confidence prediction must contain at least 30 original words.</p><a href="methodology/index.html" class="toolbarlink">Read the pricing & editorial policy →</a></div>')+'</div>'
    write('index.html',frame('Overview',body))
    body=intro('Observed listings','Event inventory','OLBG labels and IDs transcribed from the inspected public extracts. This is not a list of our picks. Raw clock labels are preserved rather than assigned an assumed timezone.', '<a class="button" href="../data/observations.csv" download>↓ Download CSV</a>')+notice()+observation_table(EVENTS)
    write('matches/index.html',frame('Event inventory',body,'Inventory',1))
    for s in SPORTS:
        entries=[x for x in EVENTS if x['sport']==s['slug']]
        body=intro('Sport research',s['name'],e(s['coverage']))+notice()
        body+='<div class="metrics">'+metric('Observed entries',str(len(entries)),'Source inspection: 26 Oct 2026')+metric('Our predictions','0','Daily target: 5')+metric('Our fair lines','0','Not fitted or calibrated')+metric('Confidence assigned','0','Evidence gate not passed')+'</div>'
        body+=box('Pricing approach · research specification','Not a production forecasting service.','<div class="bodypad"><p>'+e(s['pricing_method'])+'</p><p class="mini"><strong>Required inputs:</strong> '+e(s['required_inputs'])+'</p><p>'+''.join(pill(m)+' ' for m in s['markets'])+'</p><p class="mini">Markets to investigate, not a claim that all are currently available on OLBG. Event-specific market enumeration remains incomplete.</p><div class="sources">'+''.join(link(u,'OLBG category') for u in s['olbg_urls'])+link(s['official_url'],'Official research source')+'</div></div>')
        body+=box('Official-source inspection','Checked 2026-10-26 · limited to retrieved content','<div class="bodypad"><p>'+e(s['source_scope'])+'</p><div class="sources">'+link(s['official_url'],'Inspect official source')+'</div></div>')
        body+='<div class="sectionrow"><div><h2>Observed events & research gaps</h2><p>Unknown values are blank. Open Evidence & issues for the reason.</p></div></div>'+observation_table(entries)
        if s['slug']=='baseball':
            rows=''.join('<tr><td>'+a+'</td><td>'+b+'</td><td class="blank" aria-label="OLBG price unconfirmed"></td><td>'+link(entries[0]['olbg_url'],'OLBG event')+'</td><td>'+link(s['official_url'],'MLB schedule only')+'</td></tr>' for a,b in [('Money Line','TB Rays / MIL Brewers'),('Run Line','TB Rays +1.50 / MIL Brewers −1.50'),('Game Totals','Over 7.50 / Under 7.50')])
            body+=box('Event-level market inspection','Observed OLBG labels only. No numerical odds exposed; not our selections.',table(['Market','Displayed outcomes','OLBG odds','Market source','Official event context'],rows))
        if s['slug']=='ice-hockey':
            rows=''
            from scripts.pricing import no_vig
            for x in entries[:3]:
                q=x['official_market_quotes']; nv=no_vig(q)
                rows+=f'<tr><td>{e(x["name"])}</td><td>{q[0]:+d} / {q[1]:+d}</td><td>{nv[0]:.1%} / {nv[1]:.1%}</td><td>{link(x["official_url"],"NHL schedule · DraftKings quotes")}</td></tr>'
            body+=box('Bookmaker context · not our originated lines','Snapshot: 26 Oct 2026. Probabilities below are a mechanical no-vig benchmark, NOT independent forecasts. Order is away / home.',table(['Game','Displayed market odds','No-vig benchmark','Official source'],rows))
        write('sports/'+s['slug']+'.html',frame(s['name'],body,s['name'],1))
    build_review();build_methodology();build_discovery()
    buf=io.StringIO();fields=['id','sport','name','observed_on','raw_time','start_utc','official_date','official_start_utc','selection','fair_american','confidence','status','olbg_url','official_url','flags']
    writer=csv.DictWriter(buf,fieldnames=fields,extrasaction='ignore');writer.writeheader()
    for x in EVENTS:writer.writerow({**x,'flags':'; '.join(x['flags'])})
    write('data/observations.csv',buf.getvalue())
    write('404.html',frame('Page not found',intro('404','This page is not on the card.','Return to the overview to browse the research.')+'<a class="button" href="/Olbg8/">Back to dashboard →</a>'))
    print(f'Built {len(list(OUT.rglob("*.html")))} pages; {len(EVENTS)} observations; {len(PICKS)} picks.')

def build_review():
    issues=[('R01','All sports','No independent fitted lines, calibration, or publication-ready narratives. The 75-prediction daily target is unmet.', 'https://www.olbg.com/betting-tips', 'https://www.pgatour.com/stats'),('R02','All sports','Public category extracts contain Load More and non-exhaustive popular selections. Complete event and market discovery is not established.','https://www.olbg.com/betting-tips','https://www.icc-cricket.com/fixtures-results'),('R03','All sports','OLBG tip percentages measure tipster support. They are not our win probabilities and must not set confidence.','https://www.olbg.com/betting-tips','https://www.nhl.com/schedule/2026-10-26'),('R04','Ice Hockey','OLBG clocks are seven minutes later than NHL scheduled starts. Do not infer timezone or use the later clock to admit a pick.','https://www.olbg.com/betting-tips/Ice_Hockey/13','https://www.nhl.com/schedule/2026-10-26'),('R05','Baseball','MLB October 27 at 8 PM ET is October 28 00:00 UTC. OLBG Tomorrow 00:00 lacks timezone/date anchoring; pairing alone is not a safe event join.','https://www.olbg.com/betting-tips/Baseball/12','https://www.mlb.com/schedule/2026-10-27'),('R06','Golf','Maybank runs October 29–November 1. OLBG November 1 must not be assumed to be the tournament start.','https://www.olbg.com/betting-tips/Golf/5','https://www.lpga.com/tournaments'),('R07','Greyhounds','Expired race present; trap fields, official declarations and non-runners not established.','https://www.olbg.com/betting-tips/Greyhounds/28','https://www.gbgb.org.uk/racing/'),('R08','Basketball','NBA games page retrieved calendar counts but individual fixtures failed to render. No matchup confirmation from this page.','https://www.olbg.com/betting-tips/Basketball/4','https://www.nba.com/games?date=2026-10-26'),('R09','Rugby League','Official NRL page lists 2026 World Cup fixtures; OLBG retrieved extract only lists three 2027 outrights. Do not claim no rugby league is scheduled.','https://www.olbg.com/betting-tips/Rugby_League/10','https://www.nrl.com/draw/'),('R10','Snooker','No tips found in the OLBG extract and no tournament today in WST extract do not establish all future market availability.','https://www.olbg.com/betting-tips/Snooker/8','https://www.wst.tv/matches/'),('R11','Collection','Sandbox direct HTTPS failed. Hosted public discovery can be blocked by robots, challenge pages, or changed markup; failures must not erase the dated research snapshot.','https://www.olbg.com/betting-tips','https://www.icc-cricket.com/fixtures-results'),('R12','Handball / Cricket','Participants corroborated, but absolute timing, aliases, match ordinals and event-market joins remain incomplete.','https://www.olbg.com/betting-tips/Handball/20','https://ehfcl.eurohandball.com/men/2026-27/')]
    rows=''.join(f'<tr><td>{i}</td><td>{sport}</td><td class="reviewtext">{e(text)}</td><td>{pill("Needs review","amber")}</td><td class="sources">{link(src,"OLBG source")}{link(official,"Official research context")}</td></tr>' for i,sport,text,src,official in issues)
    body=intro('Transparent exceptions','Flagged for Review','Published limitations do not hide the research. They explain exactly why a finding is partial, a field is blank, or a selection is withheld.')+box('Priority issues','Research status, not an error-free or complete service.',table(['ID','Scope','Finding / irregularity','Status','Manual review links'],rows))
    body+='<div class="sectionrow"><div><h2>Row-by-row evidence gaps</h2><p>All observed entries remain withheld from our picks.</p></div></div>'+observation_table(EVENTS)
    write('review/index.html',frame('Flagged for Review',body,'Review',1))

def build_methodology():
    rows=''.join('<tr><td>'+s['name']+'</td><td class="reviewtext">'+e(s['pricing_method'])+'</td><td class="reviewtext">'+e(s['required_inputs'])+'</td><td>'+pill('Research only','amber')+'</td><td>'+link(s['official_url'],'Official source')+'</td></tr>' for s in SPORTS)
    body=intro('Pricing & evidence','How a finding becomes a pick.','Originate probabilities from sporting evidence first. Compare market prices second. Publish only when timing, settlement and the written reasoning are supported.')
    body+='''<section class="panel"><div class="bodypad prose"><h2>Current delivery boundary</h2><p>This is a source-inspection dashboard and research implementation, not a completed daily prediction service. No sport has a trained, backtested production pricing adapter. Mathematical kernels are tested but are not evidence of forecast accuracy. Fixtures and market coverage are partial.</p><h2>1. Find and match the event</h2><p>OLBG is the primary source for its own listing IDs and market labels. The competition, organizer or governing body is the source for participants, date, start, format, venue and official results. Match event ID, participant identities, date and settlement period before joining sources. A directory link is never fixture confirmation.</p><h2>2. Keep facts separate from estimates</h2><p>Store the source URL, retrieved content, retrieval time and claim scope. Unknown form, statistics, injuries, non-runners and availability remain blank; absence of an injury article does not mean no injuries. An independently estimated probability is an estimate, not an official fact. The currently empty fair-line fields must not be filled with market-implied probabilities.</p><h2>3. Originate and test</h2><p>Fit competition-specific parameters from official historical results with a strictly chronological train/test split. Account for home advantage, opponents, format and relevant availability. Measure held-out calibration, Brier score, log loss and sample size. Record input evidence, code version and uncertainty for each line. None of this production fitting has yet been completed.</p><p>Research kernels in <code>scripts/pricing.py</code> implement fair odds, explicit push settlement, IID first-to score distributions, regulation Poisson scores and a full-field Gaussian ranking prototype. They require supplied parameters; no default sporting strengths or simulated examples are published as real picks. Cricket innings, tennis serve rules, scoring components, overtime, retirements and race dependencies require additional sport-specific work.</p><h2>4. Compare prices without confusing popularity and probability</h2><p>Fair decimal odds with no push equal 1 / p. For a refunded push, fair decimal odds equal (1 − p_push) / p_win. At decimal odds d, expected profit per unit stake is p_win × (d − 1) − p_loss. Mechanical no-vig market benchmarks normalize implied probabilities across mutually exclusive outcomes; they are not independently originated lines.</p><p>Eligible quoted American prices are −250 through +10000, excluding invalid magnitudes below 100. A −250 quote implies 71.43% before removing margin; +10000 implies 0.99%. A high chance of winning and positive betting value are different concepts. A 78% share of OLBG tips is neither a 78% win probability nor proof of value.</p><h2>5. Confidence and editorial policy</h2><p>Low, medium and high are reserved for calibrated, evidence-complete forecasts. No confidence tier is assigned in this snapshot. Production tier thresholds require backtest support, rather than declaring all favourites high confidence. The release gate also requires future start time, fresh odds (at most 30 minutes old under this project policy), confirmed market rules and positive expected return.</p><p>Each released high-confidence prediction must be original, at least 30 words, name an explicit selection and market, and cite official evidence for form, recent results, relevant statistics and any applicable availability information. Unsupported injury claims are omitted and missing evidence prevents release. Repeated boilerplate, copied OLBG comments and the words “model” and “verified” are prohibited in prediction text. There are no published prediction paragraphs yet.</p><h2>6. Daily ranking and shortages</h2><p>Aim for five distinct qualifying matches per sport, expandable to ten when evidence supports it. Rank eligible picks by calibrated confidence and value, then separate today from upcoming using authoritative UTC starts. Do not count multiple markets on one match as five matches. A shortage is shown as a shortage; races, tournaments and out-of-season categories cannot be invented to fill a quota.</p><h2>7. Automated collection and boundaries</h2><p>A separate artifact-only workflow attempts public category-link discovery daily. It does not update this public snapshot. It checks robots.txt, rate-limits requests and records access/markup failures. It does not enumerate undocumented APIs or bypass access controls. New observations go only to the collection log, never directly to picks. Official-stat ingestion, event matching, production pricing and narrative generation are not yet automated. No user data entry is required to view the dashboard, but the full autonomous prediction pipeline remains unfinished.</p></div></section>'''
    body+=box('Sport-specific pricing specifications','Research directions, not claims of completed pricing or currently offered markets.',table(['Sport','Proposed pricing approach','Required evidence','Status','Official research source'],rows))
    rows=''.join('<tr><td>'+s['name']+'</td><td class="reviewtext">'+e(s['source_scope'])+'</td><td>2026-10-26</td><td>'+link(s['official_url'],'Official source')+'</td><td>'+''.join(link(u,'OLBG category')+'<br>' for u in s['olbg_urls'])+'</td></tr>' for s in SPORTS)
    body+=box('Official source inspection register','Content was checked through page retrieval. Not every official page exposes machine-readable fixture details.',table(['Sport','What the inspected content supports','Inspection date','Official source','OLBG source'],rows))
    body+='<p class="mini">Data: <a href="../data/observations.json">observations.json</a> · <a href="../data/sports.json">sports.json</a> · <a href="../data/audit.json">audit.json</a> · '+link('https://github.com/karagemop466-tech/Olbg8','Source code & workflows')+'</p>'
    write('methodology/index.html',frame('Pricing & sources',body,'Methodology',1))

def build_discovery():
    status=load('collection-status.json') if (ROOT/'data'/'collection-status.json').exists() else {'status':'not run','pages':[]}
    body=intro('Collection monitor','A visible trail, not a silent refresh.','Scheduled discovery records what could be retrieved. Collection success does not imply official corroboration, complete coverage or permission to publish a prediction.')
    body+=box('Latest public collection attempt',e(status.get('attempted_at','Not run')),'<div class="bodypad"><p>'+pill(status['status'],'amber')+'</p><p class="mini">'+e(status.get('error','First-page link discovery only. No exhaustive pagination or event-market coverage claim.'))+'</p><p class="mini">Historical source inspection is dated 2026-10-26 and is preserved separately. A newer discovery attempt does not refresh those facts or qualify any pick.</p><div class="sources">'+link('https://github.com/karagemop466-tech/Olbg8/actions','Workflow runs')+link('https://www.olbg.com/betting-tips','OLBG public source')+'</div></div>')
    rows=''
    for p in status.get('pages',[]):
        s=BYSLUG[p['sport']]
        rows+='<tr><td>'+s['name']+'</td><td>'+pill(p['status'],'green' if p['status']=='observed' else 'amber')+'</td><td>'+str(len(p['events']))+'</td><td class="reviewtext">'+e(p.get('error') or 'Discovered anchor labels only; unconfirmed as fixtures.')+'</td><td>'+link(p['url'],'OLBG')+'<br>'+link(s['official_url'],'Official directory only')+'</td></tr>'
    if rows:body+=box('Category retrieval results','Blocked or empty responses are not evidence of no fixtures.',table(['Category','State','Links','Notes','Sources'],rows))
    newrows=''
    for p in status.get('pages',[]):
        for ev in p.get('events',[]):
            newrows+='<tr><td>'+e(BYSLUG[p['sport']]['name'])+'</td><td>'+e(ev['label'])+'</td><td>'+e(ev['id'])+'</td><td>'+pill('Unverified','amber')+'</td><td>'+link(ev['url'],'OLBG anchor')+'<br>'+link(BYSLUG[p['sport']]['official_url'],'Official directory only')+'</td></tr>'
    if newrows:body+=box('Newly discovered labels','Unconfirmed labels: may be selections rather than event names. Not merged into the inspected snapshot.',table(['Sport','Anchor label','OLBG ID','Evidence','Sources'],newrows))
    body+='<p class="mini">Artifact-only discovery schedule: daily at 05:17 UTC (GitHub schedules can be delayed). The public snapshot does not update automatically. Download the latest workflow artifact from Workflow runs. No automatic selection publishing is enabled. <a href="../data/collection-status.json">Download collection status</a>.</p>'
    write('discovery/index.html',frame('Collection log',body,'Discovery',1))
if __name__=='__main__':
    import sys
    main()
    if '--publish' in sys.argv:
        for source in OUT.rglob('*'):
            relative=source.relative_to(OUT)
            # Preserve source data/assets; publish generated pages and CSV only.
            if source.is_file() and (source.suffix=='.html' or relative.as_posix() in ['data/observations.csv','.nojekyll']):
                target=ROOT/relative;target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(source.read_bytes())
        print('Published generated HTML/CSV in evidence-lab for existing legacy Pages.')
